-- Add reference_url column to CH_People, CH_Events, and CH_Eras.
-- Stores a canonical article URL (Wikipedia, Britannica, etc.) used to fetch
-- a description blurb at runtime. The app inspects the domain to decide which
-- API to call (e.g. Wikipedia REST summary, or a simple "Read more" link).

begin;

-- ── Add columns ─────────────────────────────────────────────────────────────

alter table public."CH_People"
  add column if not exists reference_url text;

alter table public."CH_Events"
  add column if not exists reference_url text;

alter table public."CH_Eras"
  add column if not exists reference_url text;

-- ── Seed: CH_Eras ───────────────────────────────────────────────────────────

update public."CH_Eras" set reference_url = 'https://en.wikipedia.org/wiki/Apostolic_Age'                      where era_id = 'era-apostolic';
